// features/vendor-lifecycle.feature: resubmitting without replacing the rejected document
import { expect, expectStatus, test } from "../../fixtures";

test("resubmitting without replacing the rejected w9 is refused", { tag: "@LIF-04" }, async ({ factory, apiAs }) => {
  // Arrange: a vendor in review whose w9 extraction a reviewer rejects
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const { vendor, extractions } = await factory.vendorInReview({ as: "member" });
  const rejection = await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
    data: { decision: "reject", note: "Tax ID does not match" },
  });
  await expectStatus(rejection, 200);

  // Act: the member submits again without uploading a replacement w9
  const response = await member.post(`/api/vendors/${vendor.id}/submit`);

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("documents_incomplete");
  expect(body.error.missing_kinds).toEqual(["w9"]);
});
